<?php

/* @autogenerated */
declare(strict_types=1);

namespace Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\Gateway;

use Civi\Lughauth\Features\Access\UserPersonalApiKey\Domain\UserPersonalApiKey;

class UserPersonalApiKeyCursor
{
    public const string NAME_ASC = 'name';
    public const string NAME_DESC = '-name';

    public function __construct(
        private int $limit,
        private ?string $sinceUid = null,
        private ?string $sinceName = null,
        private ?array $order = null,
    ) {
    }
    public function next(UserPersonalApiKey $userPersonalApiKey, ?int $size): UserPersonalApiKeyCursor
    {
        $next = clone $this;
        $next->sinceUid = $userPersonalApiKey->uid();
        $next->sinceName = $userPersonalApiKey->getName();
        $next->limit = $size ?? $this->limit;
        return $next;
    }
    public function limit(): int
    {
        return $this->limit;
    }
    public function sinceUid(): ?string
    {
        return $this->sinceUid;
    }
    public function sinceName(): ?string
    {
        return $this->sinceName;
    }
    public function order(): ?array
    {
        return $this->order;
    }
}
